/// 🆔️ Every collection of this family removed by row id, never by position.
pub const ID_REMOVALS: &[IdRemoval] = &[
        IdRemoval { path: "cases", kind: "remove-case", selectors: &[], id: "id" },
        IdRemoval { path: "panels[].layers", kind: "remove-panel-layer", selectors: &[SelectorKey::Id("panelId")], id: "id" },
        IdRemoval { path: "fasteners[].positions", kind: "remove-fastener-position", selectors: &[SelectorKey::Id("fastenerId")], id: "id" },
];

/// 🎯️ Resolves an editor edit into concrete kind mutations: row-id removals by [`ID_REMOVALS`], every other path through [`EDIT_RULES`].
pub fn resolve_edit(document: &En1995Snapshot, edit: &NormEdit) -> Result<Vec<En1995Mutation>, String> {
    EDIT_RULES.resolve_with_id_removals(ID_REMOVALS, document, edit)
}
